import { afterEach, describe, expect, it, vi } from 'vitest'
import { renderToStaticMarkup } from 'react-dom/server'
import UserDashboard from './app/UserDashboard'

afterEach(() => vi.unstubAllGlobals())

describe('UserDashboard', () => {
  it('fetches fresh preferences and displays each response', async () => {
    const fetchMock = vi.fn()
      .mockResolvedValueOnce({ ok: true, json: async () => ({ theme: 'dark' }) })
      .mockResolvedValueOnce({ ok: true, json: async () => ({ theme: 'light' }) })
    vi.stubGlobal('fetch', fetchMock)

    expect(renderToStaticMarkup(await UserDashboard())).toContain('dark')
    expect(renderToStaticMarkup(await UserDashboard())).toContain('light')
    expect(fetchMock).toHaveBeenCalledTimes(2)
    expect(fetchMock).toHaveBeenCalledWith('https://api.example.com/user/preferences', { cache: 'no-store' })
  })

  it('shows an unavailable message for failed requests', async () => {
    vi.stubGlobal('fetch', vi.fn().mockResolvedValue({ ok: false, status: 503 }))
    expect(renderToStaticMarkup(await UserDashboard())).toContain('Unable to load user preferences.')
  })
})
EOF
